keyConcepts.codeExample:
interface VatRate {
  readonly country: string;
  readonly rate: number;
}

const VAT_RATES: readonly VatRate[] = [
  { country: 'FR', rate: 0.2 },
  { country: 'DE', rate: 0.19 },
];

function rateFor(country: string): number {
  const entry = VAT_RATES.find(r => r.country === country);
  return entry?.rate ?? 0;
}

